import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"SectionHeader","description":"","frontmatter":{},"headers":[],"relativePath":"components/section-header.md","filePath":"components/section-header.md"}'),r={name:"components/section-header.md"};function n(i,e,h,s,c,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="sectionheader" tabindex="-1">SectionHeader <a class="header-anchor" href="#sectionheader" aria-label="Permalink to &quot;SectionHeader&quot;">​</a></h1><p>SectionHeader is a titled group inside a panel: a head with the group&#39;s name and an optional action, then the content.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to divide a panel into groups, stacked with gap 0. Text, fields and pairs go straight in; content that reaches the edges (a list, a tree, a table) takes <code>flush</code>. Use <code>rule</code> where the role changes and a line should separate the groups. On a page, use <a href="./section">Section</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>required</td><td>The name of the group</td></tr><tr><td><code>actions</code></td><td></td><td>An action on the right of the head (a snippet)</td></tr><tr><td><code>flush</code></td><td><code>false</code></td><td>The content reaches the edges</td></tr><tr><td><code>rule</code></td><td><code>false</code></td><td>Draws a line above the group</td></tr><tr><td><code>gap</code></td><td><code>sm</code></td><td><code>0</code>, <code>sm</code> or <code>md</code> between the content&#39;s children</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The head is as tall as the ink of the name (the label role), with <code>--kata-pad-md</code> at the sides; the action overlaps it without adding height, and controls in it are small buttons. The content has pad-md on its sides and below (none with <code>flush</code>) and starts pad-md below the head, so the head is closer to its content than to the group before it (pad-sm plus that group&#39;s lower padding, pad-lg first or after a line). Flush content under a head with an action keeps pad-md above it, so that the action, which hangs below the head, does not reach the first row. With <code>rule</code>, the line is pad-lg from the ink on both sides.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/section-header/" title="SectionHeader" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/section-header/" target="_blank" rel="noopener">SectionHeader</a></figcaption></figure>',10)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
